\begin{corollary}\label{corollary:1-FRFs-power-cones}
		Consider \( \gK \) and its dual cone \( \dgK \).
		\begin{enumerate}[label=(\roman*)]
			\item\label{3.6i} Let \( \bm{z}\in \bd\dgK\backslash\{\bm{0}\} \) with \( \bbz\neq \bm{0} \) and let \( \Fr := \{\bm{z}\}^\perp\cap \gK \). Let \( \gamma_{\bm{z},t} \) be defined as in \eqref{eq:gamma-1/2-1st-type-face}. Then the function \( \psi_{\gK,\bm{z}}:\R_+\times \R_+\to \R_+ \) given by\vspace{-0.15 cm}
			\begin{equation}\label{eq:1-FRF-1st-face}\vspace{-0.15 cm}
				\!\!\psi_{\gK,\bm{z}}(\epsilon,t) \!:=\! \max \left\{\epsilon,\epsilon/\|\bm{z}\| \right\} + \max\{2\sqrt{t},2\gamma_{\bm{z},t}^{-1}\}(\epsilon +\max \left\{\epsilon,\epsilon/\|\bm{z}\| \right\} )^\frac12
			\end{equation}
			is a one-step facial residual function for \( \gK \) and \( \bm{z} \).
			\item Let \( \bm{z}\in \bd\dgK\backslash\{\bm{0}\} \) with \( \bbz = \bm{0} \) and let \( \Fhatz := \{\bm{z}\}^\perp\cap \gK \). Let \( \gamma_{\bm{z},t} \) be defined as in \eqref{eq:gamma-beta-2nd-type-face}, where \( \beta:= \sum_{i:\tz_i > 0}\alpha_i \). Then the function \( \psi_{\gK,\bm{z}}:\R_+\times \R_+\to \R_+ \) given by\vspace{-0.15 cm}
			\begin{equation}\label{eq:1-FRF-2nd-face}\vspace{-0.15 cm}
				\!\!\psi_{\gK,\bm{z}}(\epsilon,t) \!:= \!\max\! \left\{\epsilon,\epsilon/\|\bm{z}\| \right\} + \max\{2t^{1-\beta}\!,2\gamma_{\bm{z},t}^{-1}\}(\epsilon +\max \left\{\epsilon,\epsilon/\|\bm{z}\| \right\} )^\beta
			\end{equation}
			is a one-step facial residual function for \( \gK \) and \( \bm{z} \).
		\end{enumerate}
	\end{corollary}

\begin{proof}
		As is shown in Section \ref{subsec:facial-structure}, all the proper exposed faces of the generalized power cone are polyhedral.
		Then the process of facial reduction needs at most one step to reach the PPS condition. Hence, \( \dpps(\gK, \subSpace + \bm{a}) \leq 1 \).
		This shows item \ref{item:error-bound-power-cone-1}.

		If \( \dpps(\gK, \subSpace + \bm{a}) = 0 \), i.e., \eqref{eq:conic-feasibility-problem} satisfies the PPS condition, then by \cite[Corollary 3]{BBL99}, a Lipschitzian error bound holds.
		This shows item \ref{item:error-bound-power-cone-2}.

		Next, let \( \dpps(\gK, \subSpace + \bm{a}) = 1 \); i.e., we need one step to reach the PPS condition.
		In this case, the error bound depends on the exposed face \( \stdFace \) that contains the feasible region.
		If \(\stdFace =  \Fr \), then by Corollary \ref{corollary:1-FRFs-power-cones}\ref{3.6i}, we conclude that a H\"olderian error bound with exponent \( 1 / 2 \) holds.
		Remark \ref{remark:F-r-order-1/2} implies that \( \mathfrak{g} = | \cdot | ^{\frac{1}{2}}\) satisfies the asymptotic optimality criterion for \( \gK \) and \( \bm{z} \) with \( \bbz \neq \bm{0} \).
		Hence, by {\cite[Theorem 3.2]{LiLoPo21}}, the obtained H\"olderian error bound with exponent \( 1 / 2 \) is the best error bound.

		If \( \stdFace = \Fhatz \) with \( \bm{z} \in \dgK \cap \subSpace^{\perp } \cap \{\bm{a}\}^{\perp } \), then using Corollary \ref{corollary:1-FRFs-power-cones}(ii), we conclude that a H\"olderian error bound with exponent \( \beta := \sum _{i \in \stdIndex} \alpha _i \) holds, where \( \stdIndex = \{i\,| \,\tz_i > 0\} \).
		The optimality of this error bound comes from Remark \ref{remark:F-z-order-beta} and {\cite[Theorem 3.2]{LiLoPo21}}.
If \( \stdFace = \{\bm{0}\} \), which means the feasible region is \( \{\bm{0}\} \), then a Lipschitzian error bound holds automatically and it is naturally tight, see \cite[Proposition~27]{L17}.
	\end{proof}

