\begin{lemma}\label{lemma:inequ-inprod-power-cone}
		Let \( n\ge 2 \) and \( \bm{\alpha} = (\alpha_1,\ldots,\alpha_n)\in (0,1)^n \) with \( \sum_{i=1}^n\alpha_i = 1 \). Let \( \bm{\zeta}\in {\rm int}\,\R_{-}^n \) satisfy \( \prod_{i=1}^n (-\zeta_i/\alpha_i)^{\alpha_i} = 1 \). Define \( \widetilde{\bm{\zeta}} := -\bm\alpha\circ \bm{\zeta}^{-1} \), where \( \circ \) is the Hadamard product and the inverse is taken componentwise. Then there exist \( C > 0 \) and \( \epsilon > 0 \) so that
		\begin{equation}\label{eq:inequ-inprod-power-cone}
			-1 - \inProd{\bm{\zeta}}{\bm{\omega}} \ge C\|\bm{\omega} - \widetilde{\bm{\zeta}}\|^2 \,\,{whenever}\,\bm{\omega}\in {\rm int}\,\R^n_+,\,\|\bm{\omega} - \widetilde{\bm{\zeta}}\|\le \epsilon {\,and\,} \prod_{i=1}^n\omega_i^{\alpha_i} = 1.
		\end{equation}
		Moreover, for any \( \bm{\omega}\in {\rm int}\,\R_+^n \) satisfying \( \prod_{i=1}^n\omega_i^{\alpha_i} = 1 \), it holds that \( \inProd{\bm{\zeta}}{\bm{\omega}}\le-1 \); furthermore, we have \( \inProd{\bm{\zeta}}{\bm{\omega}}=-1 \) if and only if \( \bm{\omega} = \widetilde{\bm{\zeta}} \).
	\end{lemma}

\begin{proposition}[Proper nontrivial exposed faces of \( \gK \)]\label{prop:facial-stru-gK}
		Let \( \bm{z} = (\bbz,\tbz)\in \bd\dgK\backslash\{\bm{0}\} \).
		\begin{enumerate}[label={(\roman*)}]
		  \item \label{item:case-I-facial-structure} If \( \bbz \neq \bm{0} \), then \( \bm{z} \) exposes the following one-dimensional face: %\( \Fr \), where
				\begin{equation}\label{eq:1st-type-face-ray}
				  \displayindent0pt
				  \displaywidth\textwidth
				  \Fr := \{\bm{z}\}^\perp\cap \gK =  \{t \bm{f}\in \R^{m+n}\,| \,t\ge 0\}\,\,\mbox{with} \,\bm{f}= (-\bbz/\|\bbz\|^2,\bm{\alpha}\circ \tbz^{-1}),
				\end{equation}
				where the inverse is taken componentwise.

		  \item \label{item:case-II-facial-structure} If \( \bbz = \bm{0} \), then \( \bm{z} \) exposes the following face of dimension \( n - | \stdIndex | \):
				\begin{equation}\label{eq:2nd-type-face-d-dim}
				  \displayindent0pt
				  \displaywidth\textwidth
				  \Fhatz := \{\bm{z}\}^\perp \cap \gK = \{\bm{x} = (\bbx,\tbx)\in \R_+^{m+n}\,| \,\bbx = \bm{0},\,\tx_i = 0\ \forall i\in \stdIndex\},
				\end{equation}
				where \( \stdIndex := \{i \,|\, \tz_i > 0\}\neq \emptyset \) and \( | \stdIndex | \) denotes the cardinality of $\stdIndex$.
		\end{enumerate}
	  \end{proposition}

\begin{proof}
	  \ref{item:case-I-facial-structure}: Notice that \( \bm{x} = (\bbx,\tbx)\in \{\bm{z}\}^\perp\cap \gK\backslash \{\bm{0}\} \) if and only if \( \bm{x}\in \bd\gK \), \( \bm{x} \neq \bm{0} \) and %satisfies
	  \begin{equation}\label{eq:inprod=0-case-I}
		\inProd{\bbz}{\bbx} + \inProd{ \tbz}{\tbx} = 0.
	  \end{equation}
	  The above relation yields
	  \begin{equation}\label{eq:inequ-sum-prod-power-case-I}
		\sum_{i=1}^n \tz_i\tx_i = -\inProd{\bbz}{\bbx}\le \|\bbz\| \|\bbx\| \le \prod_{i=1}^n\left(\frac{\tx_i\tz_i}{\alpha_i}\right)^{\alpha_i},
	  \end{equation}
	  where the last inequality follows from the definition of $\gK$ in \eqref{eq:gpowercones}.

	  Note that \( \tx_i \) cannot be \textbf{all} zero, for otherwise \( \bbx \) will also be zero since \( \bm{x}\in \bd\gK \), which contradicts \( \bm{x}\neq \bm{0} \). In addition, we must have \( \tz_i > 0 \) for all \( i \) because \( \bbz \neq \bm{0} \) and \( \bm{z}\in \bd\dgK\backslash\{\bm{0}\} \). Using these observations, we have $\sum_{i=1}^n \tz_i\tx_i >0$. Combining this with \eqref{eq:inequ-sum-prod-power-case-I}, we deduce that \( \tx_i\tz_i > 0 \) for all \( i \). Now we can take \( \ln \) on both sides of \eqref{eq:inequ-sum-prod-power-case-I} to obtain
	  \begin{equation}\label{eq:log-inequ-sum-prod-power-case-I}
		\ln\left[\sum_{i=1}^n \alpha_i\left(\frac{\tx_i\tz_i}{\alpha_i}\right)\right] \le \alpha_1\ln\left(\frac{\tx_1\tz_1}{\alpha_1}\right) + \cdots + \alpha_n\ln\left(\frac{\tx_n\tz_n}{\alpha_n}\right).
	  \end{equation}
	  Using this together with the fact that \( \ln(\cdot) \) is strictly concave, we deduce that \eqref{eq:log-inequ-sum-prod-power-case-I} holds as an equality. Hence, there exists a constant \( c > 0 \) so that
	  \begin{equation}\label{eq:form-tildex-by-tildez-case-I}
		\tx_i = c \alpha_i\tz_i^{-1}\,\,\,\forall i = 1, 2, \dots , n.
	  \end{equation}
	  Plugging \eqref{eq:form-tildex-by-tildez-case-I} into \eqref{eq:inprod=0-case-I}, we obtain
	  \begin{equation}\label{eq:inprod-barz-barx=c-case-I}
		\inProd{\bbz}{\bbx} = -\inProd{ \tbz}{\tbx} = -c\sum_{i=1}^n \alpha_i = -c.
	  \end{equation}
	  Moreover, using \eqref{eq:form-tildex-by-tildez-case-I} and the last relation in \eqref{eq:inequ-sum-prod-power-case-I}, we see that
	  \[
		\|\bbz\| \|\bbx\| \le \prod_{i=1}^n\left(\frac{\tx_i\tz_i}{\alpha_i}\right)^{\alpha_i} = c.
	  \]
	  {The two displayed lines} above show that \( \|\bbz\| \|\bbx\| = -\inProd{\bbz}{\bbx} \), which together with \( \bbz \neq \bm{0} \) implies that there exists \( \kappa > 0 \) so that
	  \begin{equation}\label{eq:form-barx-by-barz-kappa}
		\bbx = -\kappa\bbz.
	  \end{equation}
	  Plugging \eqref{eq:form-barx-by-barz-kappa} into \eqref{eq:inprod-barz-barx=c-case-I}, we obtain that \( \kappa = c/\|\bbz\|^2 \). Using this together with \eqref{eq:form-tildex-by-tildez-case-I} and \eqref{eq:form-barx-by-barz-kappa}, we can now conclude that
	  \[
		\Fr := \{\bm{z}\}^\perp\cap \gK =  \{t \bm{f}\in \R^{m+n}\,| \,t\ge 0\}\,\,\mbox{with} \,\bm{f}= (-\bbz/\|\bbz\|^2,\bm{\alpha}\circ \tbz^{-1}),
	  \]
	  where the inverse is taken componentwise.

	  \ref{item:case-II-facial-structure}: In this case, \( \bbz = \bm{0} \). Then \( \stdIndex:= \{i\,| \,\tz_i > 0\} \) is nonempty because \( \bm{z}\neq \bm{0} \). Hence, \( \bm{x} = (\bbx,\tbx)\in \{\bm{z}\}^\perp\cap \gK\backslash \{\bm{0}\} \) if and only if \( \bm{x}\in \bd\gK\backslash\{\bm{0}\} \) and satisfies
	  \begin{equation*}
		\sum_{i\in \stdIndex} \tz_i\tx_i = 0.
	  \end{equation*}
	  This means that \( \tx_i = 0 \) whenever \( i\in \stdIndex \) and hence \( \bbx= \bm{0} \). Thus,
	  \[
		\Fhatz := \{\bm{z}\}^\perp \cap \gK = \{\bm{x} = (\bbx,\tbx)\in \R_+^{m+n}\,| \,\bbx = \bm{0},\,\tx_i = 0\ \forall i\in \stdIndex\}.
	  \]
	\end{proof}

\begin{theorem}\label{thm:Holderian-1/2-1st-type-face}
		Let \( \bm{z} = (\bbz,\tbz)\in \bd\dgK\backslash\{\bm{0}\} \) with \( \bbz\neq \bm{0} \) and let \( \Fr := \{\bm{z}\}^\perp\cap \gK \). Let \( \eta > 0 \) and define
