	Then it holds that \( \left\langle \bm{f}, \bm{z} \right\rangle = 0 \) and we have
	\[
	  \| \bm{v} - \bm{w} \| = \frac{| \left\langle \bm{z}, \bm{v} \right\rangle |}{\| \bm{z} \|}, \qquad \| \bm{u} - \bm{w} \| =
	  \begin{cases}
		\left\| \bm{v} - \frac{\left\langle \bm{z}, \bm{v} \right\rangle}{\| \bm{z} \|^2}\bm{z} - \frac{\left\langle \bm{f}, \bm{v} \right\rangle}{\| \bm{f} \|^2}\bm{f} \right\| & \text{ if } \left\langle \bm{f}, \bm{v} \right\rangle \geq 0, \\
		\,\,\,\left\| \bm{v} - \frac{\left\langle \bm{z}, \bm{v} \right\rangle}{\| \bm{z} \|^2} \bm{z} \right\| & \text{ otherwise }.
	  \end{cases}
	\]
	Moreover, when \( \left\langle \bm{f}, \bm{v} \right\rangle \geq 0 \) (or, equivalently, \( \left\langle \bm{f}, \bm{w} \right\rangle \geq 0 \)), we have \( \bm{u} = P_{\Span \stdFace}(\bm{w}) \).
	On the other hand, if \( \left\langle \bm{f}, \bm{v} \right\rangle < 0 \), we have \( \bm{u} = \bm{0} \).
  \end{lemma}
}

