	  \end{equation}
	  where the last inequality follows from the definition of $\gK$ in \eqref{eq:gpowercones}.

	  Note that \( \tx_i \) cannot be \textbf{all} zero, for otherwise \( \bbx \) will also be zero since \( \bm{x}\in \bd\gK \), which contradicts \( \bm{x}\neq \bm{0} \). In addition, we must have \( \tz_i > 0 \) for all \( i \) because \( \bbz \neq \bm{0} \) and \( \bm{z}\in \bd\dgK\backslash\{\bm{0}\} \). Using these observations, we have $\sum_{i=1}^n \tz_i\tx_i >0$. Combining this with \eqref{eq:inequ-sum-prod-power-case-I}, we deduce that \( \tx_i\tz_i > 0 \) for all \( i \). Now we can take \( \ln \) on both sides of \eqref{eq:inequ-sum-prod-power-case-I} to obtain

  \begin{equation}\label{eq:log-inequ-sum-prod-power-case-I}
	\ln\left[\sum_{i=1}^n \alpha_i\left(\frac{\tx_i\tz_i}{\alpha_i}\right)\right] \le \alpha_1\ln\left(\frac{\tx_1\tz_1}{\alpha_1}\right) + \cdots + \alpha_n\ln\left(\frac{\tx_n\tz_n}{\alpha_n}\right).
  \end{equation}
  Using this together with the fact that \( \ln(\cdot) \) is strictly concave, we deduce that \eqref{eq:log-inequ-sum-prod-power-case-I} holds as an equality. Hence, there exists a constant \( c > 0 \) so that
  \begin{equation}\label{eq:form-tildex-by-tildez-case-I}
	\tx_i = c \alpha_i\tz_i^{-1}\,\,\,\forall i = 1, 2, \dots , n.
  \end{equation}

  \ref{item:case-II-facial-structure}: In this case, \( \bbz = \bm{0} \). Then \( \stdIndex:= \{i\,| \,\tz_i > 0\} \) is nonempty because \( \bm{z}\neq \bm{0} \). Hence, \( \bm{x} = (\bbx,\tbx)\in \{\bm{z}\}^\perp\cap \gK\backslash \{\bm{0}\} \) if and only if \( \bm{x}\in \bd\gK\backslash\{\bm{0}\} \) and satisfies
  \begin{equation*}
	\sum_{i\in \stdIndex} \tz_i\tx_i = 0.
  \end{equation*}
  This means that \( \tx_i = 0 \) whenever \( i\in \stdIndex \) and hence \( \bbx= \bm{0} \). Thus,
  \[
	\Fhatz := \{\bm{z}\}^\perp \cap \gK = \{\bm{x} = (\bbx,\tbx)\in \R_+^{m+n}\,| \,\bbx = \bm{0},\,\tx_i = 0\ \forall i\in \stdIndex\}.
  \]
\end{proof}

\begin{theorem}\label{thm:Holderian-1/2-1st-type-face}
		Let \( \bm{z} = (\bbz,\tbz)\in \bd\dgK\backslash\{\bm{0}\} \) with \( \bbz\neq \bm{0} \) and let \( \Fr := \{\bm{z}\}^\perp\cap \gK \). Let \( \eta > 0 \) and define
		\begin{equation}\label{eq:gamma-1/2-1st-type-face}
			\gamma_{\bm{z},\eta}\! :=\! \inf_{\bm{v}}\left\{\frac{\|\bm{v} - \bm{w}\|^\frac12}{\|\bm{u} - \bm{w}\|}\,\bigg| \,
\begin{array}{c}
\bm{v}\in \bd \gK\cap \B(\eta)\backslash \Fr,\,\bm{w} = P_{\{\bm{z}\}^\perp}(\bm{v}),\\
\bm{u} = P_{\Fr}(\bm{w}),\,\bm{u} \neq \bm{w}
\end{array}
\right\}.
		\end{equation}
		Then it holds that \( \gamma_{\bm{z},\eta}\in (0,\infty] \) and that
		\[
		\dist(\bm{q},\Fr)\le \max\{2\sqrt{\eta},2\gamma_{\bm{z},\eta}^{-1}\}\cdot\dist(\bm{q},\gK)^{\frac{1}{2}}\,\,\text{ whenever }  \bm{q} \in \{\bm{z}\}^\perp\cap \B(\eta) .
		\]
	\end{theorem}

\begin{proof}
		Suppose for a contradiction that \( \gamma_{\bm{z},\eta} = 0 \). Then, {in view of \cite[Lemma 3.12]{LiLoPo20}}, there exist \( \widehat{\bm{v}}\in \Fr \) and a sequence \( \{\bm{v}^k\}\subset \bd \gK\cap \B(\eta)\backslash \Fr \) such that
		\begin{equation}\label{eq:forcontradiction-1st-face}
			\lim_{k\to \infty}\bm{v}^k = \lim_{k\to \infty}\bm{w}^k = \widehat{\bm{v}}\,\,{\rm and}\,\,\lim_{k\to\infty}\frac{\|\bm{w}^k - \bm{v}^k\|^{\frac{1}{2}}}{\|\bm{w}^k - \bm{u}^k\|} = 0,
		\end{equation}
		where \( \bm{w}^k = P_{\{\bm{z}\}^\perp}(\bm{v}^k) \), \( \bm{u}^k = P_{\Fr}(\bm{w}^k) \) and \( \bm{u}^k\neq \bm{w}^k \).

		Define, for notational simplicity, \( z_0 := \|\bbz\| \) and \( v^k_0:=\|\bbv^k\| \).
		Then, since \( \{\bm{v}^k\}\subset \bd \gK \) and \( \bm{z} \in \bd\dgK \) with \( \bbz \neq \bm{0} \), we have\vspace{-0.15 cm}
		\begin{equation}\label{eq:z0-v0-notation}\vspace{-0.15 cm}
			z_0 = \|\bbz\| = \prod_{i=1}^n\left(\frac{\tz_i}{\alpha_i}\right)^{\alpha_i}> 0 \,\,{\rm and}\,\,v^k_0=\|\bbv^k\| = \prod_{i=1}^n(\tv_i^k)^{\alpha_i}\,\,\forall k.
		\end{equation}

		If it holds that \( v_0^k = 0 \) infinitely often, by passing to a further subsequence, we may assume that \( v_0^k = 0 \) for all \( k \). Then we have in view of {Lemma \ref{lemma:Lemma-2.11}} that\vspace{-0.15 cm}
		\[\vspace{-0.15 cm}
		\!\|\bm{v}^k - \bm{w}^k\| \!=\! \frac1{\|\bm{z}\|}|\inProd{ \tbz}{\tbv^k}|\!\overset{\rm (a)}=\! \frac1{\|\bm{z}\|}\sum_{i=1}^n\tz_i\tv^k_i\!\ge\! \frac{\min_i \tz_i}{\|\bm{z}\|} \|\tbv^k\|_1\!\ge\! \frac{\min_i \tz_i}{\|\bm{z}\|} \|\tbv^k\|
		\!\overset{\rm (b)}=\!\frac{\min_i \tz_i}{\|\bm{z}\|} \|\bm{v}^k\|,
		\]
		where (a) holds because \( \tv^k_i \ge 0 \) and \( \tz_i > 0 \) for all \( i \) (see \eqref{eq:z0-v0-notation}), and (b) holds since \( \|\bbv^k\| = 0 \). Since
		\( \|\bm{w}^k - \bm{u}^k\| = \dist(\bm{w}^k,\Fr) \le \|\bm{w}^k\|\le \|\bm{v}^k\| \) as a consequence of the properties of projections, we conclude from this and the above display that
		\( \|\bm{v}^k - \bm{w}^k\| \ge \frac{\min_i \tz_i}{\|\bm{z}\|}\|\bm{w}^k - \bm{u}^k\| \), contradicting \eqref{eq:forcontradiction-1st-face}.

		Thus, by considering a further subsequence if necessary, from now on, we assume\vspace{-0.15 cm}
		\begin{equation}\label{eq:vk0-notation-nonzero}\vspace{-0.15 cm}
			v^k_0=\|\bbv^k\| = \prod_{i=1}^n(\tv_i^k)^{\alpha_i} > 0 \,\,\forall k.
		\end{equation}
		Using {Lemma \ref{lemma:Lemma-2.11}}, we see that\vspace{-0.15 cm}
		\begin{equation}\label{eq:dist-vk-wk}\vspace{-0.15 cm}
			\begin{aligned}
				\|\bm{v}^k - \bm{w}^k\| & =\frac1{\|\bm{z}\|}|\inProd{ \bm{z}}{\bm{v}^k}| = \frac1{\|\bm{z}\|}\left|\sum_{i=1}^{m}\bz_i\bv^k_i + \sum_{i=1}^n\tz_i\tv^k_i\right|             \\
				& = \frac1{\|\bm{z}\|}\left|z_0v_0^k + \sum_{i=1}^{m}\bz_i\bv^k_i - \sum_{i=1}^n(-\tz_i)\tv^k_i - z_0v_0^k\right|                                        \\
				& = \frac{z_0v_0^k}{\|\bm{z}\|}\left| 1 + \inProd{ z_0^{-1}\bbz}{ (v_0^k)^{-1}\bbv^k} - \inProd{ z_0^{-1}(-\tbz)}{ (v_0^k)^{-1}\tbv^k} - 1\right|  \\
				& = \frac{z_0}{\|\bm{z}\|}\left( 1 + \inProd{ z_0^{-1}\bbz}{ (v_0^k)^{-1}\bbv^k} - \inProd{ z_0^{-1}(-\tbz)}{ (v_0^k)^{-1}\tbv^k} - 1\right)v_0^k,
			\end{aligned}
		\end{equation}
		where the last equality holds as \( \|z_0^{-1}\bbz\|= 1 \), \( \|(v_0^k)^{-1}\bbv^k\|= 1 \) and  \( \inProd{ z_0^{-1}\tbz}{ (v_0^k)^{-1}\tbv^k} \ge 1 \), thanks to \eqref{eq:z0-v0-notation}, \eqref{eq:vk0-notation-nonzero} and Lemma~\ref{lemma:inequ-inprod-power-cone} applied with \( \bm{\zeta} = -z_0^{-1}\tbz \).

		Let \( \bm{f} \) be defined as in \eqref{eq:1st-type-face-ray}. We consider two cases:
		\begin{enumerate}[label={(\Roman*)}]
			\item \( \inProd{ \bm{f}}{ \bm{v}^k}\ge 0 \) for all sufficiently large \( k \).
			\item \( \inProd{ \bm{f}}{ \bm{v}^k}< 0 \) infinitely often.
		\end{enumerate}

		(I): By passing to a further subsequence, we may assume that \( \inProd{ \bm{f}}{ \bm{v}^k}\ge 0 \) for all \( k \). In this case, if we define
		\[
		\bm{Q} = \bm{I}_{m + n} - \frac{\bm{z}\bm{z}^{\top}}{\|\bm{z}\|^2} - \frac{\bm{f}\bm{f}^{\top}}{\|\bm{f}\|^2},
		\]
		where \( \bm{f} \) is as in \eqref{eq:1st-type-face-ray}, then we see from {Lemma \ref{lemma:Lemma-2.11}} and \eqref{eq:z0-v0-notation} that
		\begin{equation}\label{eq:upbd-dist-uk-wk-two-parts}
			\begin{aligned}
				\|\bm{u}^k - \bm{w}^k\| & = \|\bm{Q}\bm{v}^k\| = v_0^k\left\|\bm{Q}\begin{bmatrix}
					(v_0^k)^{-1}\bbv^k \\ (v_0^k)^{-1}\tbv^k
				\end{bmatrix}\right\| \\
&\overset{\rm (a)}= v_0^k{\Bigg\|}\bm{Q}\begin{bmatrix}
					(v_0^k)^{-1}\bbv^k \\ (v_0^k)^{-1}\tbv^k
				\end{bmatrix} \!-\! \bm{Q}\underbrace{\begin{bmatrix}
						-z_0^{-1}\bbz \\ \bm{\alpha}\circ(z_0\tbz^{-1})
				\end{bmatrix}}_{z_0\bm{f}}{\Bigg\|} \\
				& \le v_0^k\left[\|(v_0^k)^{-1}\bbv^k + z_0^{-1}\bbz\| + \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|\right],
			\end{aligned}
		\end{equation}
		where (a) holds because %\( z_0\bm{f} = \begin{bmatrix}
		%		-z_0^{-1}\bbz^{\top} & \alpha\circ(z_0\tbz^{-1})^{\top}
		%	\end{bmatrix}^{\top}\)  and
		\( \bm{Q}\bm{f} = \bm{0} \) (an identity which is clear from the definitions).

		Next, in view of \eqref{eq:z0-v0-notation}, we can apply {Lemma \ref{lemma:Lemma-4.1}} to obtain \( C_1 > 0 \) and \( \epsilon_1>0 \) so that {\eqref{eq:inequ-p=q=2}} holds with \( \overline{\bm{\zeta}} = -z_0^{-1}\bbz \), i.e.,
		\[
			1 + \inProd{ z_0^{-1}\bbz}{ \bm{\omega}}\ge C_1\|\bm{\omega}  + z_0^{-1}\bbz\|^2
		\]
		whenever \( \|\bm{\omega}  + z_0^{-1}\bbz\|\le \epsilon_1 \) and \( \|\bm{\omega}\|=1 \). On the other hand, in view of the positivity of $1 + \inProd{ z_0^{-1}\bbz}{ \bm{\omega}}$ when $\|\bm{\omega}\|=1$ and $\bm{\omega} \neq -z_0^{-1}\bbz$ {(see Lemma \ref{lemma:Lemma-4.1})}, we know that
\[
C_2 := \inf_{\|\bm{\omega}\|=1}\{1 + \inProd{ z_0^{-1}\bbz}{ \bm{\omega}} \,|\, \|\bm{\omega}  + z_0^{-1}\bbz\|\ge \epsilon_1 \} > 0.
\]
This together with the fact $\|z_0^{-1}\bbz\|=1$ (see \eqref{eq:z0-v0-notation}) implies that
		\[
			1 + \inProd{ z_0^{-1}\bbz}{ \bm{\omega}}\ge C_2 \ge 0.25 C_2 \|\bm{\omega}  + z_0^{-1}\bbz\|^2,
		\]
		whenever \( \|\bm{\omega}  + z_0^{-1}\bbz\|\ge \epsilon_1 \) and \( \|\bm{\omega}\|=1 \). We thus have (with $C_3 \!:=\! \min\{C_1,C_2/4\}$)
\begin{equation}\label{eq:keylemmarel}
			1 + \inProd{ z_0^{-1}\bbz}{ \bm{\omega}}\ge C_3\|\bm{\omega}  + z_0^{-1}\bbz\|^2\ \ \ {\rm whenever}\ \ \|\bm{\omega}\|=1.
		\end{equation}

		In addition, noting \eqref{eq:z0-v0-notation} again, we can apply Lemma~\ref{lemma:inequ-inprod-power-cone} with \( \bm{\zeta} = -z_0^{-1}\tbz\in {\rm int}\,\R^n_- \) to obtain \( C_4 > 0 \) and \( \epsilon > 0 \) so that \eqref{eq:inequ-inprod-power-cone} holds with \( \widetilde{\bm{\zeta}} = \bm{\alpha}\circ (z_0\tbz^{-1}) \), i.e.,
		\begin{equation}\label{eq:keylemmare2}
			-1 + \inProd{ z_0^{-1}\tbz}{ \bm{\omega}}\ge C_4\|\bm{\omega}  - \bm{\alpha}\circ(z_0\tbz^{-1})\|^2
		\end{equation}
		whenever \( \|\bm{\omega}  - \bm{\alpha}\circ(z_0\tbz^{-1})\|\le \epsilon \), \( \bm{\omega}\in {\rm int}\,\R^n_+ \) and \( \prod_{i=1}^n\omega_i^{\alpha_i}=1 \).

%Then we have in view of the positivity of $1 + \inProd{ z_0^{-1}\bbz}{ \bm{\omega}}$ when $\bm{\omega} \neq -z_0^{-1}\bbz$ (see Lemma \ref{lemma:Lemma-4.1}) and the compactness of the unit sphere that there exists \( C_3>0 \) so that
%		\begin{equation}\label{eq:keylemmare3}
%			1 + \inProd{ z_0^{-1}\bbz}{ \bm{\omega}}\ge C_3 \|\bm{\omega}  + z_0^{-1}\bbz\|
%		\end{equation}
%		whenever \( \|\bm{\omega}  + z_0^{-1}\bbz\|\ge \epsilon \) and \( \|\bm{\omega}\|=1 \).

Furthermore, consider \( h:\R^n\to \R\cup\{\infty\} \) defined by
		\begin{equation}\label{eq:def-h}
			h(\bm{\omega}) = \begin{cases}
				\displaystyle\frac{\inProd{ z_0^{-1}\tbz}{ \bm{\omega}}-1}{\|\bm{\omega} - \bm{\alpha}\circ(z_0\tbz^{-1})\|} & {\rm if}\,\|\bm{\omega}-\bm{\alpha}\circ(z_0\tbz^{-1})\|\ge \epsilon,\,\bm{\omega}\in \Upsilon, \\
				\infty                                                                                                    & {\rm otherwise},
			\end{cases}
		\end{equation}
		where \( \Upsilon= \{\bm{\omega}\in \R^n_+\,| \,\prod_{i=1}^n \omega_i^{\alpha_i}=1\} \). Then we have
		\[
		\begin{aligned}
			& \liminf_{\|\bm{\omega}\|\to \infty}h(\bm{\omega}) = \liminf_{\|\bm{\omega}\|\to \infty, \bm{\omega}\in \Upsilon}\frac{\inProd{ z_0^{-1}\tbz}{ \bm{\omega}}-1}{\|\bm{\omega} - \bm{\alpha}\circ(z_0\tbz^{-1})\|} \\
			& \ge \liminf_{\|\bm{\omega}\|\to \infty,\bm{\omega}\in \R^n_+}\frac{\inProd{ z_0^{-1}\tbz}{ \bm{\omega}}-1}{\|\bm{\omega} - \bm{\alpha}\circ(z_0\tbz^{-1})\|}
			\overset{\rm (a)}{\ge} \inf_{\|\bm{\lambda}\|=1,\bm{\lambda}\in \R^n_+}\inProd{ z_0^{-1}\tbz}{\bm{\lambda}} \overset{\rm (b)}\ge \min_{1\le i\le n}z_0^{-1}\tz_i > 0.
		\end{aligned}
		\]
		Here (a) may be verified by multiplying both numerator and denominator of the left side by $1/\|\bm{\omega}\|$; (b) holds because \( z_0^{-1}\tz_i > 0 \) for all \( i \) (see \eqref{eq:z0-v0-notation}). Since \( h \) in \eqref{eq:def-h} is also lower semicontinuous on any compact set and {\bf is always positive},\footnote{The positivity can be seen by applying Lemma~\ref{lemma:inequ-inprod-power-cone} with $\bm\zeta = -z_0^{-1}\tbz$.} it must then hold that \( C_5:= \inf h > 0 \). In particular, this means that
		\begin{equation}\label{eq:keylemmare4}
			-1 + \inProd{ z_0^{-1}\tbz}{ \bm{\omega}}\ge C_5\|\bm{\omega}  - \bm{\alpha}\circ(z_0\tbz^{-1})\|
		\end{equation}
		whenever \( \|\bm{\omega}  - \bm{\alpha}\circ(z_0\tbz^{-1})\|\ge \epsilon \), \( \bm{\omega}\in {\rm int}\,\R^n_+ \) and \( \prod_{i=1}^n\omega_i^{\alpha_i}=1 \).

		By passing to suitable subsequences, we will end up with one of the following two cases:
		\begin{enumerate}[label={Case \arabic*:}]
			\item \( \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\| \le \epsilon \) for all \( k \). Then we have from \eqref{eq:keylemmarel} (with $\bm{\omega}=(v_0^k)^{-1}\bbv^k$) and \eqref{eq:keylemmare2} (with $\bm{\omega}=(v_0^k)^{-1}\tbv^k$) that for these \( k \)
			\begin{equation*}
				\begin{aligned}
					& 1 + \inProd{ z_0^{-1}\bbz}{ (v_0^k)^{-1}\bbv^k} - \inProd{ z_0^{-1}(-\tbz)}{ (v_0^k)^{-1}\tbv^k} - 1          \\
					& \ge \min\{C_3,C_4\}(\|(v_0^k)^{-1}\bbv^k  + z_0^{-1}\bbz\|^2 + \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|^2).
				\end{aligned}
			\end{equation*}
			Combining this with \eqref{eq:dist-vk-wk} and \eqref{eq:upbd-dist-uk-wk-two-parts}, we see further that
			\[
			\begin{aligned}
				&\|\bm{v}^k - \bm{w}^k\|\\ & \ge \frac{z_0}{\|\bm{z}\|}\min\{C_3,C_4\}(\|(v_0^k)^{-1}\bbv^k  +  z_0^{-1}\bbz\|^2 + \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|^2) v_0^k    \\
				& \ge \frac{z_0}{2\|\bm{z}\|}\min\{C_3,C_4\}(\|(v_0^k)^{-1}\bbv^k  +  z_0^{-1}\bbz\| + \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|)^2 v_0^k     \\
				& \ge \frac{z_0\min\{C_3,C_4\}}{2\|\bm{z}\|v_0^k}\|\bm{u}^k - \bm{w}^k\|^2\ge \frac{z_0\min\{C_3,C_4\}}{2\|\bm{z}\|\eta}\|\bm{u}^k - \bm{w}^k\|^2,
			\end{aligned}
			\]
			where the last inequality holds because \( \bm{v}^k\in \B(\eta) \). The above display contradicts \eqref{eq:forcontradiction-1st-face} and hence Case 1 cannot happen.

			\item \( \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|\ge \epsilon \) for all \( k \). Then we have from \eqref{eq:keylemmarel} and \eqref{eq:keylemmare4} that for these \( k \)
			\begin{equation*}
				\begin{aligned}
					& 1 + \inProd{ z_0^{-1}\bbz}{ (v_0^k)^{-1}\bbv^k} - \inProd{ z_0^{-1}(-\tbz)}{ (v_0^k)^{-1}\tbv^k} - 1        \\
					& \ge \min\{C_3,C_5\}(\|(v_0^k)^{-1}\bbv^k  + z_0^{-1}\bbz\|^2 + \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|).
				\end{aligned}
			\end{equation*}
			Using this together with \eqref{eq:dist-vk-wk}, we deduce that for all large \( k \),
			\[
			\!\|\bm{v}^k - \bm{w}^k\| \!\ge\! \frac{z_0\min\{C_3,C_5\}}{\|\bm{z}\|}(\|(v_0^k)^{-1}\bbv^k  +  z_0^{-1}\bbz\|^2 + \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|) v_0^k.
			\]
			This implies that
			\begin{equation}\label{eq:upbd-part-dist-uk-wk-case-2}
				\begin{aligned}
					\|(v_0^k)^{-1}\bbv^k  +  z_0^{-1}\bbz\|            & \le M_1\sqrt{(v_0^k)^{-1}\|\bm{v}^k - \bm{w}^k\|}, \\
					\|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\| & \le M_1(v_0^k)^{-1}\|\bm{v}^k - \bm{w}^k\|,
				\end{aligned}
			\end{equation}
			where \( M_1 := \max\left\{\left(\frac{z_0}{\|\bm{z}\|}\min\{C_3,C_5\}\right)^{-1},\left(\frac{z_0}{\|\bm{z}\|}\min\{C_3,C_5\}\right)^{-1/2}\right\} \). Using \eqref{eq:upbd-part-dist-uk-wk-case-2} together with \eqref{eq:upbd-dist-uk-wk-two-parts}, we obtain that
			\begin{equation}
			\begin{aligned}\label{eqn:3Ms}
				\|\bm{u}^k - \bm{w}^k\| & \le M_1v_0^k\left[\sqrt{(v_0^k)^{-1}\|\bm{v}^k - \bm{w}^k\|} + (v_0^k)^{-1}\|\bm{v}^k - \bm{w}^k\|\right]   \\
				%& = M_1\left(\sqrt{v_0^k} + \sqrt{\|\bm{v}^k-\bm{w}^k\|}\right)\sqrt{\|\bm{v}^k - \bm{w}^k\|}\\
				&\stackrel{\rm (a)}{\le}M_1\sqrt{\eta} \sqrt{\|\bm{v}^k-\bm{w}^k\|} + M_1\|\bm{v}^k - \bm{w}^k\| \\
				&\stackrel{\rm (b)}{\le} 3M_1\sqrt{\eta}\sqrt{\|\bm{v}^k - \bm{w}^k\|},
			\end{aligned}
			\end{equation}
			where (a) holds since \( \bm{v}^k\in \B(\eta) \) wherefore $v_0^k \leq \eta$, and (b) holds because \(\|\bm{w}^k\| \leq \|\bm{v}^k\| \le \eta \) (because the projection onto $\stdCone$ is nonexpansive and $\bm 0\in \stdCone$), wherefore
			$$
			\|\bm{w}^k-\bm{v}^k\| = \sqrt{\|\bm{w}^k-\bm{v}^k\|}\sqrt{\|\bm{w}^k-\bm{v}^k\|} \leq 2\sqrt{\eta}\sqrt{\|\bm{w}^k-\bm{v}^k\|}.
			$$
			Altogether, \eqref{eqn:3Ms} contradicts \eqref{eq:forcontradiction-1st-face} and hence Case 2 cannot happen.
		\end{enumerate}
		Summarizing the above discussions, we see that Case (I) cannot happen.

		(II):  By passing to a further subsequence, we may assume that \( \inProd{ \bm{f}}{ \bm{v}^k}< 0 \) for all \( k \). This together with the definition of \( \bm{f} \) gives
		\[
		\frac{v_0^k}{z_0}[\inProd{ -z_0^{-1}\bbz}{ (v_0^k)^{-1}\bbv^k} + \inProd{ \bm{\alpha}\circ(z_0\tbz^{-1})}{ (v_0^k)^{-1}\tbv^k}] < 0.
		\]
		Since $\frac{v_0^k}{z_0} > 0$, we deduce that $\inProd{ -z_0^{-1}\bbz}{ (v_0^k)^{-1}\bbv^k} + \inProd{ \bm{\alpha}\circ(z_0\tbz^{-1})}{ (v_0^k)^{-1}\tbv^k} < 0$ for all $k$. Then it must hold that
		\[
		\lim_{k\to \infty}\|(v_0^k)^{-1}\bbv^k + z_0^{-1}\bbz\|+\|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|\neq 0;
		\]
otherwise, we have $(v_0^k)^{-1}\bbv^k\to -z_0^{-1}\bbz$ and $(v_0^k)^{-1}\tbv^k\to \bm{\alpha}\circ(z_0\tbz^{-1})$, which further gives $\inProd{ -z_0^{-1}\bbz}{ (v_0^k)^{-1}\bbv^k} + \inProd{ \bm{\alpha}\circ(z_0\tbz^{-1})}{ (v_0^k)^{-1}\tbv^k}\to \|z_0^{-1}\bbz\|^2+\|\bm{\alpha}\circ(z_0\tbz^{-1})\|^2 = \|z_0\bm f\|^2 > 0$, a contradiction.

		Consequently, there exists $\epsilon > 0$ such that for all sufficiently large $k$,
		\begin{equation}\label{eq:sum-out-of-neighbor}
			\|(v_0^k)^{-1}\bbv^k + z_0^{-1}\bbz\|+\|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\| \ge \epsilon.
		\end{equation}
		Consider the function \( G:\R^{m+n}\to \R\cup\{\infty\} \) defined by
		\[
		G(\bm{\xi},\bm{\omega}) := \begin{cases}
			\displaystyle \frac{|\inProd{ z_0^{-1}\bbz}{ \bm{\xi}} + \inProd{ z_0^{-1}\tbz}{ \bm{\omega}}|}{\sqrt{1+\|\bm{\omega}\|^2}} & {\rm if}\,(\bm{\xi},\bm{\omega})\in \Xi,\,\|\bm{\xi}\|=1,\,{\rm and}\,\bm{\omega}\in \Upsilon, \\
			\infty                                                                                                                       & {\rm otherwise},
		\end{cases}
		\]
		where \( \Upsilon = \{\bm{\omega}\in \R^n_+\,| \,\prod_{i=1}^n \omega_i^{\alpha_i}=1\} \) and \( \Xi= \{(\bm{\xi},\bm{\omega})\,| \,\|\bm{\xi} + z_0^{-1}\bbz\|+\|\bm{\omega} - \bm{\alpha}\circ(z_0\tbz^{-1})\| \ge \epsilon\} \).
		Since \( \inProd{ z_0^{-1}\bbz}{ \bm{\xi}} + \inProd{ z_0^{-1}\tbz}{ \bm{\omega}} = 1+\inProd{ z_0^{-1}\bbz}{ \bm{\xi}} - \inProd{ z_0^{-1}(-\tbz)}{ \bm{\omega}}-1 \), we see from \eqref{eq:z0-v0-notation}, \eqref{eq:sum-out-of-neighbor}, {Lemma \ref{lemma:Lemma-4.1}} and Lemma~\ref{lemma:inequ-inprod-power-cone} that \( G \) is never zero. Moreover, it is clearly lower semicontinuous on any compact set, and
		\[
		\begin{aligned}
			\!\liminf_{\|(\bm{\xi},\bm{\omega})\|\to \infty}G(\bm{\xi},\bm{\omega}) \!=\!\!\! \liminf_{\|\bm{\omega}\|\to \infty,\bm{\omega}\in \Upsilon}\!\!\frac{|\inProd{ z_0^{-1}\tbz}{ \bm{\omega}}|}{\sqrt{1+\|\bm{\omega}\|^2}}\!\overset{\rm (a)}\ge\!\!\! \inf_{\|\bm{\lambda}\|=1,\bm{\lambda}\in \R^{n}_+}\!\!|\inProd{ z_0^{-1}\tbz}{\bm{\lambda}}|\!\overset{\rm (b)}\ge\!\! \min_i |z_0^{-1}\tz_i| > 0,
		\end{aligned}
		\]
		where (a) may be verified by multiplying numerator and denominator by $1/\|\bm{\omega}\|$ and (b) holds since \( z_0^{-1}\tz_i > 0 \) for all \( i \).
		Thus, \( C_6:= \inf G > 0 \) and we have for all large \( k \),
		\[
		\begin{aligned}
			\frac{\|\bm{v}^k - \bm{w}^k\|}{\|\bm{u}^k - \bm{w}^k\|} & \overset{\rm (a)}= \frac{\|\bm{v}^k - \bm{w}^k\|}{\|\bm{w}^k\|} \overset{\rm (b)}\ge \frac{\|\bm{v}^k - \bm{w}^k\|}{\|\bm{v}^k\|} \\
&\overset{\rm (c)}=
			\frac{z_0}{\|\bm{z}\|}\frac{|\inProd{ z_0^{-1}\bbz}{ (v_0^k)^{-1}\bbv^k} + \inProd{ z_0^{-1}\tbz}{ (v_0^k)^{-1}\tbv^k}|v_0^k}{\sqrt{(v^k_0)^2 + \|\tbv^k\|^2}}                                                                                                            \\
			& = \frac{z_0}{\|\bm{z}\|}\frac{|\inProd{ z_0^{-1}\bbz}{ (v_0^k)^{-1}\bbv^k} + \inProd{ z_0^{-1}\tbz}{ (v_0^k)^{-1}\tbv^k}|}{\sqrt{1 + \|(v_0^k)^{-1}\tbv^k\|^2}}\overset{\rm (d)}\ge \frac{C_6 z_0}{\|\bm{z}\|},
		\end{aligned}
		\]
		where (a) follows from {Lemma \ref{lemma:Lemma-2.11}}, which states that \( \bm{u}^k = \bm{0} \) in Case (II), (b) holds because the projection onto the cone is nonexpansive and $\bm 0$ is in the cone, (c) follows from \eqref{eq:dist-vk-wk} and (d) follows from \eqref{eq:sum-out-of-neighbor}, \eqref{eq:vk0-notation-nonzero} and the definitions of \( G \) and \( C_6 \). The above display contradicts \eqref{eq:forcontradiction-1st-face}. Thus, Case (II) also cannot happen.

		Summarizing the above, we conclude that \eqref{eq:forcontradiction-1st-face} cannot happen. Thus, in view of {\cite[Lemma 3.12]{LiLoPo20}}, we must indeed have \( \gamma_{\bm{z},\eta} \in (0,\infty] \) and that the desired error bound follows from {\cite[Theorem 3.10]{LiLoPo20}}.
	\end{proof}

\begin{proof}
		Suppose for a contradiction that \( \gamma_{\bm{z},\eta} = 0 \). Then, {in view of \cite[Lemma 3.12]{LiLoPo20}}, there exist \( \widehat{\bm{v}}\in \Fr \) and a sequence \( \{\bm{v}^k\}\subset \bd \gK\cap \B(\eta)\backslash \Fr \) such that
		\begin{equation}\label{eq:forcontradiction-1st-face}
			\lim_{k\to \infty}\bm{v}^k = \lim_{k\to \infty}\bm{w}^k = \widehat{\bm{v}}\,\,{\rm and}\,\,\lim_{k\to\infty}\frac{\|\bm{w}^k - \bm{v}^k\|^{\frac{1}{2}}}{\|\bm{w}^k - \bm{u}^k\|} = 0,
		\end{equation}
		where \( \bm{w}^k = P_{\{\bm{z}\}^\perp}(\bm{v}^k) \), \( \bm{u}^k = P_{\Fr}(\bm{w}^k) \) and \( \bm{u}^k\neq \bm{w}^k \).

Define, for notational simplicity, \( z_0 := \|\bbz\| \) and \( v^k_0:=\|\bbv^k\| \).
Then, since \( \{\bm{v}^k\}\subset \bd \gK \) and \( \bm{z} \in \bd\dgK \) with \( \bbz \neq \bm{0} \), we have\vspace{-0.15 cm}
\begin{equation}\label{eq:z0-v0-notation}\vspace{-0.15 cm}
	z_0 = \|\bbz\| = \prod_{i=1}^n\left(\frac{\tz_i}{\alpha_i}\right)^{\alpha_i}> 0 \,\,{\rm and}\,\,v^k_0=\|\bbv^k\| = \prod_{i=1}^n(\tv_i^k)^{\alpha_i}\,\,\forall k.
\end{equation}

Thus, by considering a further subsequence if necessary, from now on, we assume\vspace{-0.15 cm}
\begin{equation}\label{eq:vk0-notation-nonzero}\vspace{-0.15 cm}
	v^k_0=\|\bbv^k\| = \prod_{i=1}^n(\tv_i^k)^{\alpha_i} > 0 \,\,\forall k.
\end{equation}
Using {Lemma \ref{lemma:Lemma-2.11}}, we see that\vspace{-0.15 cm}
\begin{equation}\label{eq:dist-vk-wk}\vspace{-0.15 cm}
	\begin{aligned}
		\|\bm{v}^k - \bm{w}^k\| & =\frac1{\|\bm{z}\|}|\inProd{ \bm{z}}{\bm{v}^k}| = \frac1{\|\bm{z}\|}\left|\sum_{i=1}^{m}\bz_i\bv^k_i + \sum_{i=1}^n\tz_i\tv^k_i\right|             \\
		& = \frac1{\|\bm{z}\|}\left|z_0v_0^k + \sum_{i=1}^{m}\bz_i\bv^k_i - \sum_{i=1}^n(-\tz_i)\tv^k_i - z_0v_0^k\right|                                        \\
		& = \frac{z_0v_0^k}{\|\bm{z}\|}\left| 1 + \inProd{ z_0^{-1}\bbz}{ (v_0^k)^{-1}\bbv^k} - \inProd{ z_0^{-1}(-\tbz)}{ (v_0^k)^{-1}\tbv^k} - 1\right|  \\
		& = \frac{z_0}{\|\bm{z}\|}\left( 1 + \inProd{ z_0^{-1}\bbz}{ (v_0^k)^{-1}\bbv^k} - \inProd{ z_0^{-1}(-\tbz)}{ (v_0^k)^{-1}\tbv^k} - 1\right)v_0^k,
	\end{aligned}
\end{equation}
where the last equality holds as \( \|z_0^{-1}\bbz\|= 1 \), \( \|(v_0^k)^{-1}\bbv^k\|= 1 \) and  \( \inProd{ z_0^{-1}\tbz}{ (v_0^k)^{-1}\tbv^k} \ge 1 \), thanks to \eqref{eq:z0-v0-notation}, \eqref{eq:vk0-notation-nonzero} and Lemma~\ref{lemma:inequ-inprod-power-cone} applied with \( \bm{\zeta} = -z_0^{-1}\tbz \).

Let \( \bm{f} \) be defined as in \eqref{eq:1st-type-face-ray}. We consider two cases:
\begin{enumerate}[label={(\Roman*)}]
	\item \( \inProd{ \bm{f}}{ \bm{v}^k}\ge 0 \) for all sufficiently large \( k \).
	\item \( \inProd{ \bm{f}}{ \bm{v}^k}< 0 \) infinitely often.
\end{enumerate}

		(I): By passing to a further subsequence, we may assume that \( \inProd{ \bm{f}}{ \bm{v}^k}\ge 0 \) for all \( k \). In this case, if we define
		\[
		\bm{Q} = \bm{I}_{m + n} - \frac{\bm{z}\bm{z}^{\top}}{\|\bm{z}\|^2} - \frac{\bm{f}\bm{f}^{\top}}{\|\bm{f}\|^2},
		\]
		where \( \bm{f} \) is as in \eqref{eq:1st-type-face-ray}, then we see from {Lemma \ref{lemma:Lemma-2.11}} and \eqref{eq:z0-v0-notation} that
		\begin{equation}\label{eq:upbd-dist-uk-wk-two-parts}
			\begin{aligned}
				\|\bm{u}^k - \bm{w}^k\| & = \|\bm{Q}\bm{v}^k\| = v_0^k\left\|\bm{Q}\begin{bmatrix}
					(v_0^k)^{-1}\bbv^k \\ (v_0^k)^{-1}\tbv^k
				\end{bmatrix}\right\| \\
&\overset{\rm (a)}= v_0^k{\Bigg\|}\bm{Q}\begin{bmatrix}
					(v_0^k)^{-1}\bbv^k \\ (v_0^k)^{-1}\tbv^k
				\end{bmatrix} \!-\! \bm{Q}\underbrace{\begin{bmatrix}
						-z_0^{-1}\bbz \\ \bm{\alpha}\circ(z_0\tbz^{-1})
				\end{bmatrix}}_{z_0\bm{f}}{\Bigg\|} \\
				& \le v_0^k\left[\|(v_0^k)^{-1}\bbv^k + z_0^{-1}\bbz\| + \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|\right],
			\end{aligned}
		\end{equation}
		where (a) holds because %\( z_0\bm{f} = \begin{bmatrix}
		%		-z_0^{-1}\bbz^{\top} & \alpha\circ(z_0\tbz^{-1})^{\top}
		%	\end{bmatrix}^{\top}\)  and
		\( \bm{Q}\bm{f} = \bm{0} \) (an identity which is clear from the definitions).

In addition, noting \eqref{eq:z0-v0-notation} again, we can apply Lemma~\ref{lemma:inequ-inprod-power-cone} with \( \bm{\zeta} = -z_0^{-1}\tbz\in {\rm int}\,\R^n_- \) to obtain \( C_4 > 0 \) and \( \epsilon > 0 \) so that \eqref{eq:inequ-inprod-power-cone} holds with \( \widetilde{\bm{\zeta}} = \bm{\alpha}\circ (z_0\tbz^{-1}) \), i.e.,
\begin{equation}\label{eq:keylemmare2}
	-1 + \inProd{ z_0^{-1}\tbz}{ \bm{\omega}}\ge C_4\|\bm{\omega}  - \bm{\alpha}\circ(z_0\tbz^{-1})\|^2
\end{equation}
whenever \( \|\bm{\omega}  - \bm{\alpha}\circ(z_0\tbz^{-1})\|\le \epsilon \), \( \bm{\omega}\in {\rm int}\,\R^n_+ \) and \( \prod_{i=1}^n\omega_i^{\alpha_i}=1 \).

%Then we have in view of the positivity of $1 + \inProd{ z_0^{-1}\bbz}{ \bm{\omega}}$ when $\bm{\omega} \neq -z_0^{-1}\bbz$ (see Lemma \ref{lemma:Lemma-4.1}) and the compactness of the unit sphere that there exists \( C_3>0 \) so that
%		\begin{equation}\label{eq:keylemmare3}
%			1 + \inProd{ z_0^{-1}\bbz}{ \bm{\omega}}\ge C_3 \|\bm{\omega}  + z_0^{-1}\bbz\|
%		\end{equation}
%		whenever \( \|\bm{\omega}  + z_0^{-1}\bbz\|\ge \epsilon \) and \( \|\bm{\omega}\|=1 \).

Furthermore, consider \( h:\R^n\to \R\cup\{\infty\} \) defined by
		\begin{equation}\label{eq:def-h}
			h(\bm{\omega}) = \begin{cases}
				\displaystyle\frac{\inProd{ z_0^{-1}\tbz}{ \bm{\omega}}-1}{\|\bm{\omega} - \bm{\alpha}\circ(z_0\tbz^{-1})\|} & {\rm if}\,\|\bm{\omega}-\bm{\alpha}\circ(z_0\tbz^{-1})\|\ge \epsilon,\,\bm{\omega}\in \Upsilon, \\
				\infty                                                                                                    & {\rm otherwise},
			\end{cases}
		\end{equation}
		where \( \Upsilon= \{\bm{\omega}\in \R^n_+\,| \,\prod_{i=1}^n \omega_i^{\alpha_i}=1\} \). Then we have
		\[
		\begin{aligned}
			& \liminf_{\|\bm{\omega}\|\to \infty}h(\bm{\omega}) = \liminf_{\|\bm{\omega}\|\to \infty, \bm{\omega}\in \Upsilon}\frac{\inProd{ z_0^{-1}\tbz}{ \bm{\omega}}-1}{\|\bm{\omega} - \bm{\alpha}\circ(z_0\tbz^{-1})\|} \\
			& \ge \liminf_{\|\bm{\omega}\|\to \infty,\bm{\omega}\in \R^n_+}\frac{\inProd{ z_0^{-1}\tbz}{ \bm{\omega}}-1}{\|\bm{\omega} - \bm{\alpha}\circ(z_0\tbz^{-1})\|}
			\overset{\rm (a)}{\ge} \inf_{\|\bm{\lambda}\|=1,\bm{\lambda}\in \R^n_+}\inProd{ z_0^{-1}\tbz}{\bm{\lambda}} \overset{\rm (b)}\ge \min_{1\le i\le n}z_0^{-1}\tz_i > 0.
		\end{aligned}
		\]
		Here (a) may be verified by multiplying both numerator and denominator of the left side by $1/\|\bm{\omega}\|$; (b) holds because \( z_0^{-1}\tz_i > 0 \) for all \( i \) (see \eqref{eq:z0-v0-notation}). Since \( h \) in \eqref{eq:def-h} is also lower semicontinuous on any compact set and {\bf is always positive},\footnote{The positivity can be seen by applying Lemma~\ref{lemma:inequ-inprod-power-cone} with $\bm\zeta = -z_0^{-1}\tbz$.} it must then hold that \( C_5:= \inf h > 0 \). In particular, this means that
		\begin{equation}\label{eq:keylemmare4}
			-1 + \inProd{ z_0^{-1}\tbz}{ \bm{\omega}}\ge C_5\|\bm{\omega}  - \bm{\alpha}\circ(z_0\tbz^{-1})\|
		\end{equation}
		whenever \( \|\bm{\omega}  - \bm{\alpha}\circ(z_0\tbz^{-1})\|\ge \epsilon \), \( \bm{\omega}\in {\rm int}\,\R^n_+ \) and \( \prod_{i=1}^n\omega_i^{\alpha_i}=1 \).

By passing to suitable subsequences, we will end up with one of the following two cases:
\begin{enumerate}[label={Case \arabic*:}]
	\item \( \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\| \le \epsilon \) for all \( k \). Then we have from \eqref{eq:keylemmarel} (with $\bm{\omega}=(v_0^k)^{-1}\bbv^k$) and \eqref{eq:keylemmare2} (with $\bm{\omega}=(v_0^k)^{-1}\tbv^k$) that for these \( k \)
	\begin{equation*}
		\begin{aligned}
			& 1 + \inProd{ z_0^{-1}\bbz}{ (v_0^k)^{-1}\bbv^k} - \inProd{ z_0^{-1}(-\tbz)}{ (v_0^k)^{-1}\tbv^k} - 1          \\
			& \ge \min\{C_3,C_4\}(\|(v_0^k)^{-1}\bbv^k  + z_0^{-1}\bbz\|^2 + \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|^2).
		\end{aligned}
	\end{equation*}
	Combining this with \eqref{eq:dist-vk-wk} and \eqref{eq:upbd-dist-uk-wk-two-parts}, we see further that
	\[
	\begin{aligned}
		&\|\bm{v}^k - \bm{w}^k\|\\ & \ge \frac{z_0}{\|\bm{z}\|}\min\{C_3,C_4\}(\|(v_0^k)^{-1}\bbv^k  +  z_0^{-1}\bbz\|^2 + \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|^2) v_0^k    \\
		& \ge \frac{z_0}{2\|\bm{z}\|}\min\{C_3,C_4\}(\|(v_0^k)^{-1}\bbv^k  +  z_0^{-1}\bbz\| + \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|)^2 v_0^k     \\
		& \ge \frac{z_0\min\{C_3,C_4\}}{2\|\bm{z}\|v_0^k}\|\bm{u}^k - \bm{w}^k\|^2\ge \frac{z_0\min\{C_3,C_4\}}{2\|\bm{z}\|\eta}\|\bm{u}^k - \bm{w}^k\|^2,
	\end{aligned}
	\]
	where the last inequality holds because \( \bm{v}^k\in \B(\eta) \). The above display contradicts \eqref{eq:forcontradiction-1st-face} and hence Case 1 cannot happen.

	\item \( \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|\ge \epsilon \) for all \( k \). Then we have from \eqref{eq:keylemmarel} and \eqref{eq:keylemmare4} that for these \( k \)
	\begin{equation*}
		\begin{aligned}
			& 1 + \inProd{ z_0^{-1}\bbz}{ (v_0^k)^{-1}\bbv^k} - \inProd{ z_0^{-1}(-\tbz)}{ (v_0^k)^{-1}\tbv^k} - 1        \\
			& \ge \min\{C_3,C_5\}(\|(v_0^k)^{-1}\bbv^k  + z_0^{-1}\bbz\|^2 + \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|).
		\end{aligned}
	\end{equation*}
	Using this together with \eqref{eq:dist-vk-wk}, we deduce that for all large \( k \),
	\[
	\!\|\bm{v}^k - \bm{w}^k\| \!\ge\! \frac{z_0\min\{C_3,C_5\}}{\|\bm{z}\|}(\|(v_0^k)^{-1}\bbv^k  +  z_0^{-1}\bbz\|^2 + \|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\|) v_0^k.
	\]
	This implies that
	\begin{equation}\label{eq:upbd-part-dist-uk-wk-case-2}
		\begin{aligned}
			\|(v_0^k)^{-1}\bbv^k  +  z_0^{-1}\bbz\|            & \le M_1\sqrt{(v_0^k)^{-1}\|\bm{v}^k - \bm{w}^k\|}, \\
			\|(v_0^k)^{-1}\tbv^k - \bm{\alpha}\circ(z_0\tbz^{-1})\| & \le M_1(v_0^k)^{-1}\|\bm{v}^k - \bm{w}^k\|,
		\end{aligned}
	\end{equation}
	where \( M_1 := \max\left\{\left(\frac{z_0}{\|\bm{z}\|}\min\{C_3,C_5\}\right)^{-1},\left(\frac{z_0}{\|\bm{z}\|}\min\{C_3,C_5\}\right)^{-1/2}\right\} \). Using \eqref{eq:upbd-part-dist-uk-wk-case-2} together with \eqref{eq:upbd-dist-uk-wk-two-parts}, we obtain that
	\begin{equation}
	\begin{aligned}\label{eqn:3Ms}
		\|\bm{u}^k - \bm{w}^k\| & \le M_1v_0^k\left[\sqrt{(v_0^k)^{-1}\|\bm{v}^k - \bm{w}^k\|} + (v_0^k)^{-1}\|\bm{v}^k - \bm{w}^k\|\right]   \\
		%& = M_1\left(\sqrt{v_0^k} + \sqrt{\|\bm{v}^k-\bm{w}^k\|}\right)\sqrt{\|\bm{v}^k - \bm{w}^k\|}\\
		&\stackrel{\rm (a)}{\le}M_1\sqrt{\eta} \sqrt{\|\bm{v}^k-\bm{w}^k\|} + M_1\|\bm{v}^k - \bm{w}^k\| \\
		&\stackrel{\rm (b)}{\le} 3M_1\sqrt{\eta}\sqrt{\|\bm{v}^k - \bm{w}^k\|},
	\end{aligned}
	\end{equation}
	where (a) holds since \( \bm{v}^k\in \B(\eta) \) wherefore $v_0^k \leq \eta$, and (b) holds because \(\|\bm{w}^k\| \leq \|\bm{v}^k\| \le \eta \) (because the projection onto $\stdCone$ is nonexpansive and $\bm 0\in \stdCone$), wherefore
	$$
	\|\bm{w}^k-\bm{v}^k\| = \sqrt{\|\bm{w}^k-\bm{v}^k\|}\sqrt{\|\bm{w}^k-\bm{v}^k\|} \leq 2\sqrt{\eta}\sqrt{\|\bm{w}^k-\bm{v}^k\|}.
	$$
	Altogether, \eqref{eqn:3Ms} contradicts \eqref{eq:forcontradiction-1st-face} and hence Case 2 cannot happen.
\end{enumerate}
Summarizing the above discussions, we see that Case (I) cannot happen.

Moreover, we have
\[
\begin{aligned}
	&\prod_{i=1}^n (\widetilde{\bm{q}}_\epsilon)_i^{\alpha_i}  = (\alpha_1 - \epsilon)^{\alpha_1}(\alpha_2 + \epsilon)^{\alpha_2}\tz_1^{-\alpha_1}\tz_2^{-\alpha_2}\prod_{i=3}^n\left(\frac{\alpha_i}{\tz_i}\right)^{\alpha_i}          \\
	& =  \left(1 - \frac{\epsilon}{\alpha_1}\right)^{\alpha_1}\left(1 + \frac{\epsilon}{\alpha_2}\right)^{\alpha_2}\prod_{i=1}^n\left(\frac{\alpha_i}{\tz_i}\right)^{\alpha_i}
	\overset{\rm (a)}= \left(1 - \frac{\epsilon}{\alpha_1}\right)^{\alpha_1}\left(1 + \frac{\epsilon}{\alpha_2}\right)^{\alpha_2} \|\bbz\|^{-1}                                                                                          \\
	& = \left(1 - \frac{\epsilon}{\alpha_1}\right)^{\alpha_1}\left(1 + \frac{\epsilon}{\alpha_2}\right)^{\alpha_2}\|\bar{\bm{q}}_\epsilon\|,
\end{aligned}
\]
where (a) holds because \( \bm{z}\in \bd\dgK\backslash\{\bm{0}\} \) with \( \bbz\neq \bm{0} \). In view of this, if we define a continuous function \( \bm{p}:(0,\alpha_1)\to \gK \)  by $\epsilon \mapsto \bm{p}_\epsilon := (\bar{\bm{p}}_\epsilon,\widetilde{\bm{p}}_\epsilon)$ where
\[
\bar{\bm{p}}_\epsilon := -\left(1 - \frac{\epsilon}{\alpha_1}\right)^{\alpha_1}\left(1 + \frac{\epsilon}{\alpha_2}\right)^{\alpha_2}\frac{\bbz}{\|\bbz\|^2}\quad{\rm and}\quad \widetilde{\bm{p}}_\epsilon := \widetilde{\bm{q}}_\epsilon;
\]
then it is clear that \( \bm{p}_\epsilon \in \gK \), and we can compute that
\begin{equation}\label{eq:distpower}
	\begin{aligned}
		\dist(\bm{q}_\epsilon,\gK) & \le \|\bm{q}_\epsilon - \bm{p}_\epsilon\| = \frac1{\|\bbz\|}\left|\left(1 - \frac{\epsilon}{\alpha_1}\right)^{\alpha_1}\left(1 + \frac{\epsilon}{\alpha_2}\right)^{\alpha_2} - 1\right| \\
		& = \frac1{\|\bbz\|}\left|(1 - \epsilon + O(\epsilon^2))(1 + \epsilon + O(\epsilon^2)) - 1\right| = O(\epsilon^2).
	\end{aligned}
\end{equation}

\begin{theorem}\label{thm:xface}
		Let \( \bm{z}\in \bd\dgK\backslash\{\bm{0}\} \) with \( \bbz = \bm{0} \) and let \( \Fhatz := \{\bm{z}\}^\perp\cap \gK \). Let \( \stdIndex := \{i\,| \,\tz_i > 0\} \),\footnote{Since \( \bbz = \bm{0} \) and \( \bm{z}\in \bd\dgK\backslash\{\bm{0}\} \), we must have \( \emptyset\neq \stdIndex \subsetneq \{1,2,\ldots,n\} \).} \( \eta > 0 \) and define \( \beta:= \sum_{i\in \stdIndex}\alpha_i \) and
		\begin{equation}\label{eq:gamma-beta-2nd-type-face}
		 \!\gamma_{\bm{z},\eta} \!:=\! \inf_{\bm{v}}\left\{\frac{\|\bm{v} - \bm{w}\|^\beta}{\|\bm{u} - \bm{w}\|}\,\bigg| \,
\begin{array}{c}
\bm{v}\in \bd \gK\cap \B(\eta)\backslash \Fhatz,\,\bm{w} = P_{\{\bm{z}\}^\perp}(\bm{v}),\\
\bm{u} = P_{\Fhatz}(\bm{w}),\,\bm{u} \neq \bm{w}
\end{array}\right\}.
		\end{equation}
