%		$$
		To that end, let \( \bm{v}\in \bd \gK\cap \B(\eta)\backslash \Fhatz \), \( \bm{w} = P_{\{\bm{z}\}^\perp}(\bm{v}) \), \( \bm{u} = P_{\Fhatz}(\bm{w}) \), and \( \bm{u} \neq \bm{w} \). Then a direct computation shows
		that
		\begin{equation}\label{eq:dist-w-v}
			\|\bm{w}- \bm{v}\| = \frac1{\|\bm{z}\|}|\inProd{ \bm{z}}{\bm{v}}| \overset{\rm (a)}= \frac1{\|\bm{z}\|}\sum_{i\in \stdIndex}\tz_i\tv_i \overset{\rm (b)}\ge \frac{\min_{i\in \stdIndex}\tz_i}{\|\bm{z}\|}\sum_{i\in \stdIndex}\tv_i
			\overset{\rm (c)}\ge \frac{\min_{i\in \stdIndex}\tz_i}{\|\bm{z}\|}\|\tbv_{\stdIndex}\|,
		\end{equation}
		where (a), (b) and (c) hold because \( \tv_i\ge 0 \) and \( \tz_i > 0 \) for all \( i\in \stdIndex \), with \( \|\tbv_{\stdIndex}\|:= \sqrt{\sum_{i\in \stdIndex}\tv^2_i} \) (note that \( \stdIndex \neq \emptyset \), thanks to \( \bbz = 0 \) and \( \bm{z}\neq \bm{0} \)). Next, notice that \( \bm{w} = \bm{v} - \frac{\inProd{ \bm{z}}{\bm{v}}}{\|\bm{z}\|^2}\bm{z} \). Using this and the definitions of \( \bm{z} \) and \( \stdIndex \), we deduce that
		\begin{equation}\label{eq:form-w-by-v}
			\bbw = \bbv,\,\,\,\tw_i = \tv_i - \frac{\tz_i}{\|\bm{z}\|^2}\bigg(\sum_{j\in \stdIndex}\tz_j\tv_j\bigg)\,\,\,\, \forall i\in \stdIndex\,\,\,\,\,\,\,\mbox{and\,\,\,\,\,\,\,} \tw_i = \tv_i \ge 0\,\,\,\,\forall i \notin \stdIndex.
		\end{equation}
		In view of this and the definition of \( \Fhatz \) in \eqref{eq:2nd-type-face-d-dim}, we see that \( \tu_i = \tw_i \) whenever \( i\notin \stdIndex \), and hence
		\begin{equation}\label{eq:dist-w-u}
			\|\bm{w} - \bm{u}\| = \sqrt{\|\bbw\|^2 + \sum_{i\in \stdIndex}\tw^2_i} \le \sqrt{\|\bbv\|^2 + n(1+\sqrt{n})^2\|\tbv_{\stdIndex}\|^2},
		\end{equation}
		where the inequality follows from \eqref{eq:form-w-by-v} and the fact that for each \( i\in \stdIndex \),
