			|\tw_i| & = \bigg|\tv_i - \frac{\tz_i}{\|\bm{z}\|^2}\bigg(\sum_{j\in \stdIndex}\tz_j\tv_j\bigg)\bigg|\le \bigg(1 + \frac{|\tz_i|}{\|\bm{z}\|^2}\sum_{j\in \stdIndex}|\tz_j|\bigg)\|\tbv_{\stdIndex}\| \\
			& \le \left(1 + \frac{\sqrt{n}|\tz_i|}{\|\bm{z}\|}\right)\|\tbv_{\stdIndex}\| \le (1+\sqrt{n})\|\tbv_{\stdIndex}\|.
