			= \eta^{1-\beta} \|\tbv_{\stdIndex}\|^\beta,
		\end{equation}
		where the inequality holds because \( \bm{v}\in \B(\eta) \). Combining \eqref{eq:dist-w-v}, \eqref{eq:dist-w-u} and \eqref{eq:upbd-norm-bar-v}, we deduce
		\[
		\begin{aligned}
			\|\bm{w} - \bm{u}\| & \le \sqrt{\|\bbv\|^2 + n(1+\sqrt{n})^2\|\tbv_{\stdIndex}\|^2} \le \|\bbv\| + (n+\sqrt{n})\|\tbv_{\stdIndex}\|                                                                                                     \\
			& \le \eta^{1-\beta} \|\tbv_{\stdIndex}\|^\beta + (n+\sqrt{n})\|\tbv_{\stdIndex}\| = (\eta^{1-\beta}  + (n+\sqrt{n})\|\tbv_{\stdIndex}\|^{1-\beta})\|\tbv_{\stdIndex}\|^\beta                                   \\
			& \overset{\rm (a)}\le \eta^{1-\beta}(n+1 + \sqrt{n})\|\tbv_{\stdIndex}\|^\beta \overset{\rm (b)}{\le}\frac{\eta^{1-\beta}(n+1 + \sqrt{n})\|\bm{z}\|^\beta}{\left(\min_{i\in_{\stdIndex}}\tz_i\right)^\beta}\|\bm{w}-\bm{v}\|^\beta.
		\end{aligned}
		\]
		Here (a) holds since \( \bm{v}\in \B(\eta) \) and \( \beta \in (0,1) \); (b) is true because of \eqref{eq:dist-w-v}.
		Thus, \( \gamma_{\bm{z},\eta}\ge \frac{\left(\min_{i\in \stdIndex}\tz_i\right)^\beta}{\eta^{1-\beta}(n+1 + \sqrt{n})\|\bm{z}\|^\beta} > 0 \), and the desired error bound {follows from \cite[Theorem 3.10]{LiLoPo20}}.
	\end{proof}

